const mean=a=>a.length?a.reduce((s,v)=>s+v,0)/a.length:null;
const available=v=>typeof v==='number'&&Number.isFinite(v);
const number=(v,d=2)=>available(v)?v.toFixed(d):'未提供';
function waterCut(r,density){if(!r||!available(r.water_m3)||!(r.density_t_per_m3??density))return null;const oil=r.oil_tonnes/(r.density_t_per_m3??density);return oil+r.water_m3>0?100*r.water_m3/(oil+r.water_m3):null;}
export function assessPdp(run,cases=[],{density=.85}={}){const latest=run.latest,reference=run.December,current=run.current.find(r=>r.month===latest.month),wc=waterCut(latest,density),wc0=waterCut(reference,density),wcDelta=available(wc)&&available(wc0)?wc-wc0:null,pDelta=available(latest.pressure_mpa)&&available(reference?.pressure_mpa)?latest.pressure_mpa-reference.pressure_mpa:null,wellDelta=reference?.active_wells>0?100*(latest.active_wells/reference.active_wells-1):null,oilChange=current?.deviation??null,petroleum=[],actions=[],gaps=[];
 if(available(wellDelta)&&wellDelta<=-5){petroleum.push('在产井数较年末变化'+number(wellDelta)+'%，存在停井/设备可用性损失候选；须核对井清单和开井时长。');actions.push({priority:'1 · 运行核实',measure:'逐井核查停井、检泵、计量与输送限制，区分产能损失与储层递减；具备条件的已有井制定恢复计划。',evidence:'在产井数变化'+number(wellDelta)+'%',confirm:'停井台账、设备工况、平均开井小时与单井产能'});}
 if(available(wcDelta)&&wcDelta>=5){petroleum.push('含水率较年末上升'+number(wcDelta)+'个百分点，水窜或高含水层无效循环为候选原因，尚不能单凭曲线确诊。');actions.push({priority:'2 · 控水诊断',measure:'补充吸水/产液剖面和示踪剂，确认优势通道后比选分层调剖、堵水或产液结构调整。',evidence:'月度含水率变化'+number(wcDelta)+'个百分点',confirm:'分层剖面、示踪剂、井间响应与措施适用层段'});}
 if(available(pDelta)&&pDelta<=-.5){petroleum.push('压力较年末变化'+number(pDelta)+'兆帕，地层能量亏空或压力口径变化为候选解释。');actions.push({priority:'2 · 能量核验',measure:'先确认压力为同口径地层静压，再用PVT折算地下体积注采平衡，按吸水能力和破裂压力约束比选配注。',evidence:'月度压力变化'+number(pDelta)+'兆帕',confirm:'静压/流压口径、PVT、注水压力、分层吸水指数与供水能力'});}
 if(run.updatedModel.annualDecline>(run.baselineModel?.annualDecline??Infinity)+.05){petroleum.push('更新阶段的有效年递减率较冻结基准加快，可能存在储层/工况阶段变化；应分阶段复核模型适用性。');actions.push({priority:'3 · 模型复评',measure:'复核计量、措施和停井影响后选择稳定段，更新阶段物性、递减参数与经济极限，保留原计划版本。',evidence:'年递减率：冻结'+number((run.baselineModel?.annualDecline??NaN)*100)+'%，更新'+number(run.updatedModel.annualDecline*100)+'%',confirm:'当前阶段物性、生产制度、成本和有效合同等评估依据'});}
 if(!actions.length){petroleum.push('现有指标尚不足以锁定原因，先进行数据质量与生产制度复核；本月未触发规则不等于已证明无风险。');actions.push({priority:'1 · 证据补齐',measure:'复核月报、开井时长及计量，联合剖面、压力和历史措施资料后再决定治理措施。',evidence:current?.reason??'暂无当年可比月',confirm:'诊断所需独立监测与生产记录'});}
 if(!available(wcDelta))gaps.push('缺少年末/当前产水或密度资料，不能比较含水变化');if(!available(pDelta))gaps.push('缺少年末/当前同口径压力');if(!available(wellDelta))gaps.push('缺少年末已有在产井基准');gaps.push('未提供可证实措施因果效果的对照或现场试验；不自动承诺增油与PDP增加');
 const features={oil_change_pct:oilChange,water_cut_delta_pp:wcDelta,pressure_delta_mpa:pDelta,availability_change_pct:wellDelta},scales={oil_change_pct:20,water_cut_delta_pp:10,pressure_delta_mpa:2,availability_change_pct:20},ranked=cases.map(c=>{const keys=Object.keys(scales).filter(k=>available(features[k])&&available(c[k]));return {...c,commonFeatures:keys.length,distance:keys.length>=2?Math.sqrt(mean(keys.map(k=>((features[k]-c[k])/scales[k])**2))):null};}).filter(c=>c.distance!==null).sort((a,b)=>a.distance-b.distance).slice(0,3);
 const statistics=['当前可比月份累计偏差为'+number(run.metrics.cumulativeDeviation)+'%；MAE='+number(run.metrics.MAE)+'吨/月，RMSE='+number(run.metrics.RMSE)+'吨/月。','图中95%均值置信区间反映参数估计不确定性；95%单月预测区间还包含未来月度扰动，均为条件性、点位区间。',current?.p_lower!==null&&current?.p_lower!==undefined?'最新观测的正态近似单侧下尾概率='+number(current.p_lower,6)+'，按12个月Bonferroni校正后='+number(current.p_adjusted,6)+'；这不是储量失效或某根因的概率。':'原计划未提供误差机制或有效预测区间时，不计算伪造的尾概率。','负向CUSUM最新值='+number(current?.cusum)+'（k=0.5、H=5），用于持续偏移提示；工程百分比阈值和CUSUM并用，不能当作独立重复证据。'];
 return {month:latest.month,level:current?.level??'灰',source:run.source,petroleum,statistics,cases:ranked,features,actions,gaps,followup:['下月：核验计量、停井清单与当月预警是否持续；逐井确认执行条件。','措施后1个月：用独立无措施基线比较实际产量和含水、压力变化。','措施后3个月：复核效果持续性、预测覆盖与剖面响应，必要时重新校准。','措施后6个月：评价累计增油与经济效果；满足适用评估依据后再开展正式储量重评。'],conclusion:'建议按“先核实运行损失，再验证控水/能量原因，最后复评模型与经济极限”推进。措施效果须现场验证；预测与置信区间不等于已证实增油或认证PDP。'};}
export function pdpText(run,report){return `SEC/PDP月度动态监测研究报告\n数据来源：${run.source}\n冻结日：${run.freezeDate}；截至月：${run.asOf}；预测起算观测月：${run.forecastOrigin}\n基准来源：${run.baselineSource}\n累计实际：${number(run.metrics.actualTotal)}吨；同期冻结预测：${number(run.metrics.predictedTotal)}吨；偏差${number(run.metrics.cumulativeDeviation)}%\n\n石油专业研判\n${report.petroleum.join('\n')}\n\n统计与区间\n${report.statistics.join('\n')}\n\n历史模式对照\n${report.cases.map(c=>`${c.id}（${c.source}）：标准化距离${number(c.distance,3)}；${c.conclusion}`).join('\n')||'证据不足，未匹配类比案例。'}\n\n下一步措施\n${report.actions.map(a=>`${a.priority}：${a.measure}\n依据：${a.evidence}\n待确认：${a.confirm}`).join('\n')}\n\n跟踪计划\n${report.followup.join('\n')}\n\n结论\n${report.conclusion}\n\n限制与缺口\n${report.gaps.join('\n')}\n${run.intervalNote}\n此为研究监测与决策支持，不是经认证的SEC储量报告。`;}
